package dev.metallicarts.domain;
import com.mojang.serialization.JsonOps;
import dev.metallicarts.arts.*;
import dev.metallicarts.config.AdvancedConfig;
import dev.metallicarts.equipment.*;
import dev.metallicarts.feruchemy.*;
import dev.metallicarts.hemalurgy.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CompoundingTest {
 private final UUID identity=UUID.randomUUID(),player=UUID.randomUUID();private final AssetLease lease=new AssetLease(player,0);
 private MetalmindAsset source(MetalmindLedger l,FeruchemicalAttribute a,MetalmindContent content){var s=l.claim(l.create(a,100000,1,false,content).token(),new AssetLease(player,1));s=l.change(s.token(),s.lease().orElseThrow(),identity,1000);return l.release(s.token(),s.lease().orElseThrow());}
 @Test void amplificationConsumesOneCanonicalSourceAndCopiesCannotRepeat(){var l=new MetalmindLedger();var s=source(l,FeruchemicalAttribute.HEALTH,MetalmindContent.EMPTY);var d=l.claim(l.create(FeruchemicalAttribute.HEALTH,100000,1,false).token(),lease);var result=l.compound(s.token(),d.token(),lease,identity,identity,false,10);assertEquals(10000,result.charge());assertTrue(l.find(s.token().instance()).orElseThrow().consumed());assertThrows(IllegalArgumentException.class,()->l.resolve(s.token()));assertThrows(IllegalArgumentException.class,()->l.compound(s.token(),d.token(),lease,identity,identity,false,10));assertEquals(10000,l.resolve(d.token()).charge());}
 @Test void failedCapacityAttributeOrIdentityPreflightLeavesBothRecordsUntouched(){var l=new MetalmindLedger();var s=source(l,FeruchemicalAttribute.SPEED,MetalmindContent.EMPTY);var d=l.claim(l.create(FeruchemicalAttribute.SPEED,1000,1,false).token(),lease);var before=l.all();assertThrows(IllegalArgumentException.class,()->l.compound(s.token(),d.token(),lease,identity,identity,false,10));assertEquals(before,l.all());var big=l.claim(l.create(FeruchemicalAttribute.SPEED,100000,1,false).token(),new AssetLease(player,2));l.change(big.token(),big.lease().orElseThrow(),UUID.randomUUID(),1);assertThrows(IllegalArgumentException.class,()->l.compound(s.token(),big.token(),big.lease().orElseThrow(),identity,identity,false,10));assertFalse(l.resolve(s.token()).consumed());}
 @Test void typedInvestitureCannotBeLaunderedIntoAnotherAbility(){var l=new MetalmindLedger();var a=new MetalmindContent(Optional.of(new StoredPower(Art.FERUCHEMY,Metal.GOLD,1)),List.of(),false);var b=new MetalmindContent(Optional.of(new StoredPower(Art.ALLOMANCY,Metal.STEEL,1)),List.of(),false);var s=source(l,FeruchemicalAttribute.INVESTITURE,a);var d=l.claim(l.create(FeruchemicalAttribute.INVESTITURE,100000,1,false,b).token(),lease);assertThrows(IllegalArgumentException.class,()->l.compound(s.token(),d.token(),lease,identity,identity,false,10));assertEquals(1000,l.resolve(s.token()).charge());}
 @Test void consumedTombstoneAndExactOutputSurviveCodecRestart(){var l=new MetalmindLedger();var s=source(l,FeruchemicalAttribute.WEIGHT,MetalmindContent.EMPTY);var d=l.claim(l.create(FeruchemicalAttribute.WEIGHT,100000,1,false).token(),lease);l.compound(s.token(),d.token(),lease,identity,identity,false,10);var loaded=MetalmindLedger.CODEC.parse(JsonOps.INSTANCE,MetalmindLedger.CODEC.encodeStart(JsonOps.INSTANCE,l).getOrThrow()).getOrThrow();assertEquals(l.all(),loaded.all());assertThrows(IllegalArgumentException.class,()->loaded.claim(s.token(),new AssetLease(UUID.randomUUID(),2)));}
 @Test void copperBurnMovesExactMemoriesOnceWithoutCreatingExtraKnowledge(){var l=new MetalmindLedger();var s=l.claim(l.create(FeruchemicalAttribute.MEMORY,100000,1,false).token(),lease);var memory=new MemoryEntry(UUID.randomUUID(),"actual","Found a refuge","minecraft:overworld",1,80,2,1);s=l.storeMemory(s.token(),lease,identity,memory,false);s=l.release(s.token(),lease);var token=s.token();assertEquals(List.of(memory),l.burnMemories(token,identity));assertThrows(IllegalArgumentException.class,()->l.burnMemories(token,identity));}
 @Test void rateChangesPreserveFractionalMachineTimeAndRepeatCallsCannotDoubleTick(){var clock=new FractionalClock();assertEquals(0,clock.advance(1,.25));assertEquals(0,clock.advance(2,.25));assertEquals(1,clock.advance(3,.5));assertEquals(0,clock.advance(3,4));assertEquals(3,clock.advance(4,3));assertEquals(0,clock.advance(5,.25));}
 @Test void settingsMergeDefaultsAndRejectDangerousValues(){var defaults=AdvancedConfig.parse("{}");assertEquals(AdvancedConfig.DEFAULT,defaults);assertThrows(RuntimeException.class,()->AdvancedConfig.parse("{\"time\":{\"maximum\":100}}"));assertThrows(RuntimeException.class,()->AdvancedConfig.parse("{\"emotions\":{\"recovery\":-1}}"));assertThrows(RuntimeException.class,()->AdvancedConfig.parse("{\"compounding\":{\"multiplier\":0}}"));}
 @Test void genericArtSpikesCannotPretendToBeBlessingsOrKolossStaples(){var l=new SpikeLedger();var a=l.create(Metal.STEEL,new StolenPower(StolenPower.Kind.ALLOMANCY,Metal.STEEL),UUID.randomUUID(),identity,UUID.randomUUID(),1,0);var b=l.create(Metal.STEEL,new StolenPower(StolenPower.Kind.ALLOMANCY,Metal.STEEL),UUID.randomUUID(),identity,UUID.randomUUID(),1,0);var prep=new ConstructLedger();assertThrows(IllegalArgumentException.class,()->prep.bless(a,b));assertThrows(IllegalArgumentException.class,()->prep.prepare(a,ConstructLedger.Purpose.KOLOSS_STAPLE));assertTrue(prep.all().isEmpty());}
 @Test void pairedBlessingsRemainCanonicalAndPersist(){var l=new SpikeLedger();var a=l.create(Metal.IRON,new StolenPower(StolenPower.Kind.STRENGTH,Metal.IRON),UUID.randomUUID(),identity,UUID.randomUUID(),1,0);var b=l.create(Metal.IRON,new StolenPower(StolenPower.Kind.STRENGTH,Metal.IRON),UUID.randomUUID(),identity,UUID.randomUUID(),1,0);var prep=new ConstructLedger();prep.bless(a,b);assertEquals(prep.find(a.token().instance()).orElseThrow().pair(),prep.find(b.token().instance()).orElseThrow().pair());var loaded=ConstructLedger.CODEC.parse(JsonOps.INSTANCE,ConstructLedger.CODEC.encodeStart(JsonOps.INSTANCE,prep).getOrThrow()).getOrThrow();assertEquals(prep.all(),loaded.all());assertThrows(IllegalArgumentException.class,()->prep.bless(a,b));}
}
